// t11_matrix -- generated by gen_t11_matrix.py; do not edit by hand.
// Expectations from tools/model/fp32.py (exact products, one rounding per
// addition, increasing k order -- ISA sec 9C.1).
.org 0
start:
    // ---- mbarrier: arrivals only ----
    mb.init   b0
    mb.arm    s1, b0, #2, #0
    mb.test   s2, s1
    .assert_eq s2, #0, #1
    mb.arrive b0
    mb.test   s2, s1
    .assert_eq s2, #0, #2
    mb.arrive b0
    mb.test   s2, s1
    .assert_eq s2, #1, #3
    mb.wait   s1                  // already complete: must not block

    // a second generation on the same barrier is independent
    mb.arm    s3, b0, #1, #0
    mb.test   s4, s3
    .assert_eq s4, #0, #4
    mb.arrive b0
    mb.wait   s3
    mb.test   s4, s3
    .assert_eq s4, #1, #5

    // ---- accumulator ----
    a.zero    a0
    .li       s5, #3
    a.vread   v1, a0, s5
    .assert_lane v1, #0, #0x00000000, #6
    .assert_lane v1, #7, #0x00000000, #7
    .assert_lane v1, #15, #0x00000000, #8

    .li       s6, #10240
    v.ld.w    v2, [s6, #0]
    a.vwrite  a0, s5, v2
    a.vread   v3, a0, s5
    .assert_lane v3, #0, #0xc23351d1, #9
    .assert_lane v3, #5, #0x4272ea82, #10
    .assert_lane v3, #15, #0xc2895885, #11
    // a different row must be untouched
    .li       s7, #4
    a.vread   v4, a0, s7
    .assert_lane v4, #0, #0x00000000, #12

    // a.mul.row: one rounding, not a multiply then an add
    .li       s8, #0x40400000       // 3.0f
    a.mul.row a0, s5, s8
    a.vread   v3, a0, s5
    .assert_lane v3, #0, #0xc3067d5d, #13
    .assert_lane v3, #5, #0x43362fe2, #14
    .assert_lane v3, #15, #0xc34e04c8, #15

    // a.fma.row: acc = fma(acc, scale, Vx)
    v.ld.w    v5, [s6, #64]
    .li       s9, #0xbf000000      // -0.5f
    a.fma.row a0, s5, v5, s9
    a.vread   v3, a0, s5
    .assert_lane v3, #0, #0x4252d121, #16
    .assert_lane v3, #5, #0xc2c3bd1c, #17
    .assert_lane v3, #15, #0x430bdaeb, #18

    // masked accumulator write leaves inactive lanes alone
    a.zero    a2
    v.iota    v6
    v.cmpi.lt p1, v6, #8
    @p1 a.vwrite a2, s5, v2
    a.vread   v7, a2, s5
    .assert_lane v7, #3, #0x408a49d2, #19
    .assert_lane v7, #11, #0x00000000, #20

    // ---- m.mma.async: C = A.B, completion through a barrier ----
    .li       s10, #8192
    v.ld.w    v32, [s10, #0]
    v.ld.w    v33, [s10, #64]
    v.ld.w    v34, [s10, #128]
    v.ld.w    v35, [s10, #192]
    v.ld.w    v36, [s10, #256]
    v.ld.w    v37, [s10, #320]
    v.ld.w    v38, [s10, #384]
    v.ld.w    v39, [s10, #448]
    .li       s11, #9216
    v.ld.w    v40, [s11, #0]
    v.ld.w    v41, [s11, #64]
    v.ld.w    v42, [s11, #128]
    v.ld.w    v43, [s11, #192]
    v.ld.w    v44, [s11, #256]
    v.ld.w    v45, [s11, #320]
    v.ld.w    v46, [s11, #384]
    v.ld.w    v47, [s11, #448]
    m.zero    a1
    mb.init   b1
    mb.arm    s12, b1, #0, #1     // one asynchronous operation
    m.mma.async a1, v32, v40, s12
    mb.wait   s12                 // sleeps until the engine signals

    .li       s13, #0
    a.vread   v8, a1, s13
    .assert_lane v8, #0, #0x42a6e02a, #21
    .assert_lane v8, #1, #0xc11aa9e0, #22
    .assert_lane v8, #8, #0xc00cc040, #23
    .assert_lane v8, #15, #0xc2d88d3a, #24
    .li       s13, #1
    a.vread   v8, a1, s13
    .assert_lane v8, #0, #0xc230a2a8, #25
    .assert_lane v8, #1, #0xc33956a0, #26
    .assert_lane v8, #8, #0xc1610148, #27
    .assert_lane v8, #15, #0xc30d9d00, #28
    .li       s13, #7
    a.vread   v8, a1, s13
    .assert_lane v8, #0, #0x41c183e0, #29
    .assert_lane v8, #1, #0x42c04bba, #30
    .assert_lane v8, #8, #0x41b4af48, #31
    .assert_lane v8, #15, #0xc1beec70, #32
    .li       s13, #14
    a.vread   v8, a1, s13
    .assert_lane v8, #0, #0xc30db640, #33
    .assert_lane v8, #1, #0x42ae9260, #34
    .assert_lane v8, #8, #0xc237fa67, #35
    .assert_lane v8, #15, #0x432a8960, #36
    .li       s13, #15
    a.vread   v8, a1, s13
    .assert_lane v8, #0, #0xc29b8fdd, #37
    .assert_lane v8, #1, #0xc2a4fd15, #38
    .assert_lane v8, #8, #0x424c0134, #39
    .assert_lane v8, #15, #0x430c0ce0, #40

    // A second MMA accumulates onto the same C: 2*A.B
    mb.arm    s12, b1, #0, #1
    m.mma.async a1, v32, v40, s12
    mb.wait   s12
    .li       s13, #0
    a.vread   v8, a1, s13
    .assert_lane v8, #0, #0x4326e02a, #41
    .assert_lane v8, #15, #0xc3588d3a, #42
    .li       s13, #9
    a.vread   v8, a1, s13
    .assert_lane v8, #0, #0xc237b1cc, #43
    .assert_lane v8, #15, #0xc29fe380, #44

    exit

.org 0x2000
